 rebuildGeometry(){this.model=projectionModel(this.state.shape,this.state.dimensions);this.views=projectionViews(this.model,this.state.scale);this.cols=Math.ceil(Math.max(...Object.values(this.views).map(v=>v.width))+2);this.rows=Math.ceil(Math.max(...Object.values(this.views).map(v=>v.height))+2);}
