   for(let y=0;y<=this.rows+1e-8;y+=this.model.gridStep)board.grid.append(uiSvg('line',{x1:0,y1:y*projDrawingPixels,x2:cellW,y2:y*projDrawingPixels,class:Math.abs(y-Math.round(y))<1e-8?'projection-grid-major':'projection-grid-minor'}));
