   board.drawing.replaceChildren();board.feedback.replaceChildren();board.cursor.replaceChildren();const revealed=this.state.mode==='guide'&&(view==='plan'&&this.state.guideStep>=1||view==='front'&&this.state.guideStep>=2||view==='side'&&this.state.guideStep>=3);
   if(revealed){for(const p of this.views[view].primitives)this.stroke(board.drawing,p);if(view==='plan'&&this.state.shape==='cone'){const centre=this.sheetPoint(this.views.plan.primitives[0].center);board.drawing.append(uiSvg('circle',{cx:centre[0],cy:centre[1],r:3,class:'projection-apex'}),uiSvg('text',{x:centre[0]+8,y:centre[1]-8,class:'projection-board-label'},this.t('apex')));}}
